	domMatch := !s.domRestricted || s.daysOfMonth[t.Day()]
	dowMatch := !s.dowRestricted || s.daysOfWeek[int(t.Weekday())]
	switch {
	case !s.domRestricted && !s.dowRestricted:
		return true
	case s.domRestricted && s.dowRestricted:
