// Package schedule parses five-field UTC cron expressions and computes the
// next matching instant after a given time.
package schedule

import (
	"errors"
	"strconv"
	"strings"
	"time"
)

// Schedule is a parsed five-field cron expression.
type Schedule struct {
	minutes       [60]bool
	hours         [24]bool
	daysOfMonth   [32]bool // index 1..31
	months        [13]bool // index 1..12
	daysOfWeek    [7]bool  // index 0 = Sunday
	domRestricted bool
	dowRestricted bool
