type apiFixture struct {
	t      *testing.T
	router http.Handler
}

func newFixture(t *testing.T) *apiFixture {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return &apiFixture{t: t, router: NewRouter(st)}
}

func (f *apiFixture) do(method, target string, body any) *httptest.ResponseRecorder {
	f.t.Helper()
	var reader *bytes.Reader
	if body != nil {
		raw, err := json.Marshal(body)
		if err != nil {
			f.t.Fatalf("marshal: %v", err)
		}
		reader = bytes.NewReader(raw)
	} else {
		reader = bytes.NewReader(nil)
	}
	req := httptest.NewRequest(method, target, reader)
	req.Header.Set("Content-Type", "application/json")
	rec := httptest.NewRecorder()
	f.router.ServeHTTP(rec, req)
	return rec
}

func decodeJob(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	var payload struct {
		Job      string         `json:"job"`
		Schedule string         `json:"schedule"`
		Attempts []map[string]any `json:"attempts"`
		Raw      map[string]any `json:"-"`
	}
	var raw map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &raw); err != nil {
		t.Fatalf("decode %s: %v", rec.Body.String(), err)
	}
	return raw
}

func errorCode(rec *httptest.ResponseRecorder) string {
	var payload struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &payload); err != nil {
		return ""
	}
	return payload.Error.Code
}

func createValidJob(t *testing.T, f *apiFixture) map[string]any {
	t.Helper()
	rec := f.do(http.MethodPost, "/api/v1/jobs", map[string]any{
		"job": "nightly", "schedule": "0 2 * * *", "maxRetries": 2,
	})
	if rec.Code != http.StatusCreated {
		t.Fatalf("create status = %d body = %s", rec.Code, rec.Body.String())
	}
	job := decodeJob(t, rec)
	if job["job"] != "nightly" || job["schedule"] != "0 2 * * *" {
		t.Fatalf("unexpected job state: %v", job)
	}
	if paused, _ := job["paused"].(bool); paused {
		t.Fatal("new job must be unpaused")
	}
	if retries := job["retries"].(float64); retries != 0 {
		t.Fatalf("retries = %v, want 0", retries)
	}
	nextRun, ok := job["nextRunAt"].(string)
	if !ok || nextRun == "" {
		t.Fatalf("nextRunAt missing: %v", job)
	}
	if _, err := time.Parse(time.RFC3339, nextRun); err != nil {
		t.Fatalf("nextRunAt not RFC3339: %v", nextRun)
	}
	attempts, _ := job["attempts"].([]any)
	if len(attempts) != 0 {
		t.Fatalf("attempts = %v, want empty", attempts)
	}
	return job
}

